77 — 78 — 79 — □ — 81',ARRAY['M1-2-u1-X05','M1-2-u1-X06']::text[],false,'{"seq":7,"concept":"M1-2-u1-C5","difficulty":2,"kind":"blank","stem":"수를 순서대로 늘어놓았어요. 빈칸에 알맞은 수를 고르세요.\n77 — 78 — 79 — □ — 81","options":[{"t":"80","correct":true},{"t":"90","mis":"M1-2-u1-X05"},{"t":"710","mis":"M1-2-u1-X06"}],"explanation":["79 다음은 80이에요.","낱개 9 다음은 묶음이 하나 늘어나요.","묶음 8개와 낱개 0개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;

