INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u1-X01','math',1,'u1',ARRAY['M1-2-u1-C2','M1-2-u1-C3']::text[],'자리를 바꿔 쓴다 — 23을 32로','묶음이 앞, 낱개가 뒤. 묶음 수를 먼저 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u1-X02','math',1,'u1',ARRAY['M1-2-u1-C1']::text[],'몇십을 낱개처럼 센다 — 70을 "일곱"','묶음 하나가 10이라는 것을 묶음 그림으로 다시 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u1-X03','math',1,'u1',ARRAY['M1-2-u1-C2']::text[],'낱개 10개를 묶음으로 바꾸지 않는다','낱개가 10이 되면 묶어야 한다는 규칙을 손으로 묶어 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u1-X04','math',1,'u1',ARRAY['M1-2-u1-C3']::text[],'두 가지 읽기를 섞는다 — 23을 "스물삼"','이십삼 / 스물셋을 두 줄로 적어 통째로 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u1-X05','math',1,'u1',ARRAY['M1-2-u1-C5']::text[],'몇십의 문턱을 넘지 못한다 — 79 다음을 70 또는 90','79 → 80 에서 묶음이 하나 느는 것을 배열판에서 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u1-X06','math',1,'u1',ARRAY['M1-2-u1-C5']::text[],'1만큼 큰 수를 십의 자리에 적용 — 79보다 1 큰 수를 89','1은 낱개 하나. 배열판에서 바로 오른쪽 칸을 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u1-X07','math',1,'u1',ARRAY['M1-2-u1-C6']::text[],'낱개부터 비교한다 — 37 > 52','묶음(십의 자리)을 먼저. 묶음 수가 다르면 거기서 끝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u1-X08','math',1,'u1',ARRAY['M1-2-u1-C6']::text[],'숫자 모양·길이로 크다고 본다','수는 개수. 묶음 그림으로 두 수를 나란히 놓기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u1-X09','math',1,'u1',ARRAY['M1-2-u1-C7']::text[],'짝수·홀수를 큰 수·작은 수로 안다','둘씩 짝지어 남는 게 있으면 홀수 — 크기와 무관') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u1-X10','math',1,'u1',ARRAY['M1-2-u1-C1','M1-2-u1-C3']::text[],'0을 빠뜨린다 — 70을 7로 쓴다','낱개가 없어도 0을 써야 자리가 지켜진다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u1-X11','math',1,'u1',ARRAY['M1-2-u1-C5']::text[],'99 다음을 모른다 — 90 또는 991','99에서 낱개 하나 더 = 묶음 10개 = 100') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L02_basic#1','math',1,2,'u1','L02','g1_2_math_u1_L02_basic','lesson_basic','M1-2-u1-C1',1,'mc','auto','그림을 보세요. 얼마인가요?',ARRAY['M1-2-u1-X02','M1-2-u1-X01']::text[],true,'{"seq":1,"concept":"M1-2-u1-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 얼마인가요?","asset":{"type":"bundle_ones","tens":6,"ones":0},"options":[{"t":"60","correct":true},{"t":"6","mis":"M1-2-u1-X02"},{"t":"16","mis":"M1-2-u1-X01"}],"explanation":["10개씩 묶음이 6개예요.","묶음 6개는 60이에요.","묶음 하나는 낱개 10개와 같아요."],"variant_rule":{"bundle":{"tens":[6,9],"ones":[0,0],"ask":"number"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L02_basic#2','math',1,2,'u1','L02','g1_2_math_u1_L02_basic','lesson_basic','M1-2-u1-C1',1,'sa','auto','그림이 나타내는 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u1-C1","difficulty":1,"kind":"sa","stem":"그림이 나타내는 수를 숫자로 쓰세요.","asset":{"type":"bundle_ones","tens":7,"ones":0},"answer":["70"],"explanation":["10개씩 묶음이 7개예요.","묶음 7개는 70이라고 써요.","묶음 수를 앞에, 낱개 0을 뒤에 써요."],"variant_rule":{"bundle":{"tens":[6,9],"ones":[0,0],"ask":"number"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L02_basic#3','math',1,2,'u1','L02','g1_2_math_u1_L02_basic','lesson_basic','M1-2-u1-C1',1,'mc','auto','70을 두 가지로 바르게 읽은 것은 무엇인가요?',ARRAY['M1-2-u1-X02','M1-2-u1-X04']::text[],false,'{"seq":3,"concept":"M1-2-u1-C1","difficulty":1,"kind":"mc","stem":"70을 두 가지로 바르게 읽은 것은 무엇인가요?","options":[{"t":"칠십, 일흔","correct":true},{"t":"칠, 일곱","mis":"M1-2-u1-X02"},{"t":"칠십, 일곱","mis":"M1-2-u1-X04"}],"explanation":["70은 칠십 또는 일흔이라고 읽어요.","칠·일곱은 7을 읽는 말이에요.","두 가지 읽기를 섞어 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L02_basic#4','math',1,2,'u1','L02','g1_2_math_u1_L02_basic','lesson_basic','M1-2-u1-C1',1,'match','auto','묶음의 수와 알맞은 수를 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M1-2-u1-C1","difficulty":1,"kind":"match","stem":"묶음의 수와 알맞은 수를 이어 보세요.","pairs":[{"l":"10개씩 묶음 6개","r":"60"},{"l":"10개씩 묶음 8개","r":"80"},{"l":"10개씩 묶음 9개","r":"90"}],"explanation":["묶음 하나는 10이에요.","묶음이 6개면 60, 8개면 80이에요.","묶음 수 뒤에 0을 붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L02_basic#5','math',1,2,'u1','L02','g1_2_math_u1_L02_basic','lesson_basic','M1-2-u1-C1',2,'mc','auto','그림을 보세요. 10개씩 묶음은 몇 개인가요?',ARRAY['M1-2-u1-X02','M1-2-u1-X01']::text[],true,'{"seq":5,"concept":"M1-2-u1-C1","difficulty":2,"kind":"mc","stem":"그림을 보세요. 10개씩 묶음은 몇 개인가요?","asset":{"type":"bundle_ones","tens":8,"ones":0},"options":[{"t":"8","correct":true},{"t":"80","mis":"M1-2-u1-X02"},{"t":"7","mis":"M1-2-u1-X01"}],"explanation":["묶음을 하나씩 세어요.","묶음은 8개예요.","묶음 8개가 나타내는 수는 80이에요."],"variant_rule":{"bundle":{"tens":[6,9],"ones":[0,0],"ask":"tens"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L02_basic#6','math',1,2,'u1','L02','g1_2_math_u1_L02_basic','lesson_basic','M1-2-u1-C1',2,'sa','auto','10개씩 묶음 9개는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-2-u1-C1","difficulty":2,"kind":"sa","stem":"10개씩 묶음 9개는 얼마인가요? 숫자로 쓰세요.","asset":{"type":"bundle_ones","tens":9,"ones":0},"answer":["90"],"explanation":["묶음 하나는 10이에요.","묶음 9개는 90이에요.","아흔이라고도 읽어요."],"variant_rule":{"bundle":{"tens":[6,9],"ones":[0,0],"ask":"number"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
