INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L02_basic#8','math',1,2,'u1','L02','g1_2_math_u1_L02_basic','lesson_basic','M1-2-u1-C1',2,'ox','auto','이 그림이 나타내는 수는 80입니다.',ARRAY['M1-2-u1-X08']::text[],false,'{"seq":8,"concept":"M1-2-u1-C1","difficulty":2,"kind":"ox","stem":"이 그림이 나타내는 수는 80입니다.","asset":{"type":"bundle_ones","tens":8,"ones":0},"answer":"O","reason_options":[{"t":"10개씩 묶음이 8개라서","correct":true},{"t":"묶음이 8줄로 길어서","mis":"M1-2-u1-X08"}],"explanation":["묶음을 세면 8개예요.","묶음 8개는 80이에요.","묶음 하나를 10으로 세는 것이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
