INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L02_basic#10','math',1,2,'u1','L02','g1_2_math_u1_L02_basic','lesson_basic','M1-2-u1-C1',3,'sa','auto','70보다 10만큼 더 큰 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u1-C1","difficulty":3,"kind":"sa","stem":"70보다 10만큼 더 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["10만큼 크면 묶음이 하나 늘어나요.","묶음 7개에서 8개가 되니 80이에요.","낱개는 그대로 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
