INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L02_challenge#10','math',1,2,'u1','L02','g1_2_math_u1_L02_challenge','lesson_challenge','M1-2-u1-C1',4,'essay','teacher','60, 70, 80, 90을 큰 수부터 차례로 쓰고, 어떻게 알았는지 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u1-C1","difficulty":4,"kind":"essay","stem":"60, 70, 80, 90을 큰 수부터 차례로 쓰고, 어떻게 알았는지 말해 보세요.","answer_guide":"90, 80, 70, 60 순으로 쓰고 「10개씩 묶음 수가 많을수록 큰 수」라는 까닭을 말하면 통과.","explanation":["묶음 수를 세어 비교해요.","묶음이 많을수록 큰 수예요.","90 — 80 — 70 — 60 순서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
