INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L03_challenge#10','math',1,2,'u1','L03','g1_2_math_u1_L03_challenge','lesson_challenge','M1-2-u1-C2',4,'essay','teacher','63과 36은 어떻게 다른지, 묶음과 낱개를 써서 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u1-C2","difficulty":4,"kind":"essay","stem":"63과 36은 어떻게 다른지, 묶음과 낱개를 써서 설명해 보세요.","answer_guide":"63은 묶음 6개와 낱개 3개, 36은 묶음 3개와 낱개 6개라는 점을 「자리」로 구분해 말하면 통과.","explanation":["63은 묶음 6개와 낱개 3개예요.","36은 묶음 3개와 낱개 6개예요.","같은 숫자라도 자리에 따라 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
