INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L06_challenge#10','math',1,2,'u1','L06','g1_2_math_u1_L06_challenge','lesson_challenge','M1-2-u1-C5',4,'essay','teacher','99 다음 수가 100인 까닭을 묶음과 낱개를 써서 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u1-C5","difficulty":4,"kind":"essay","stem":"99 다음 수가 100인 까닭을 묶음과 낱개를 써서 말해 보세요.","answer_guide":"「99는 묶음 9개와 낱개 9개 → 낱개가 하나 늘면 낱개 10개가 되어 묶음 1개로 바뀜 → 묶음 10개 = 100」의 흐름이 나오면 통과.","explanation":["99는 묶음 9개와 낱개 9개예요.","낱개가 하나 늘면 낱개가 10개가 돼요.","낱개 10개를 묶으면 묶음 10개, 곧 100이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
