INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L07_challenge#10','math',1,2,'u1','L07','g1_2_math_u1_L07_challenge','lesson_challenge','M1-2-u1-C6',4,'essay','teacher','63과 58 중에서 어느 수가 더 큰지 쓰고, 어떻게 알았는지 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u1-C6","difficulty":4,"kind":"essay","stem":"63과 58 중에서 어느 수가 더 큰지 쓰고, 어떻게 알았는지 말해 보세요.","answer_guide":"63이 크다고 답하고 「묶음(십의 자리)을 먼저 비교했다 — 6개와 5개」라는 까닭을 말하면 통과. 낱개(3과 8)로 판단했다면 다시 지도.","explanation":["묶음을 먼저 봐요 — 6개와 5개예요.","묶음이 많은 63이 커요.","낱개 3과 8은 나중에 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
