INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_L08_challenge#10','math',1,2,'u1','L08','g1_2_math_u1_L08_challenge','lesson_challenge','M1-2-u1-C7',4,'essay','teacher','우리 반 학생 수가 짝수인지 홀수인지 알아보는 방법을 말해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u1-C7","difficulty":4,"kind":"essay","stem":"우리 반 학생 수가 짝수인지 홀수인지 알아보는 방법을 말해 보세요.","answer_guide":"「두 명씩 짝을 지어 남는 사람이 있는지 본다」는 방법이 나오면 통과. 실제 반 학생 수를 넣어 말하면 더 좋다.","explanation":["두 명씩 짝을 지어 보세요.","남는 사람이 없으면 짝수예요.","한 명이 남으면 홀수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
