INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_a#20','math',1,2,'u1','review','g1_2_math_u1_review_a','unit_review','M1-2-u1-C7',3,'sa','auto','사탕 13개를 두 개씩 나누어 담았어요. 남는 사탕은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":20,"concept":"M1-2-u1-C7","difficulty":3,"kind":"sa","stem":"사탕 13개를 두 개씩 나누어 담았어요. 남는 사탕은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["13은 둘씩 짝지으면 하나가 남아요.","남는 사탕은 1개예요.","그래서 13은 홀수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
