INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_b#11','math',1,2,'u1','review','g1_2_math_u1_review_b','unit_review','M1-2-u1-C3',2,'sa','auto','"예순셋"을(를) 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M1-2-u1-C3","difficulty":2,"kind":"sa","stem":"\"예순셋\"을(를) 숫자로 쓰세요.","answer":["63"],"explanation":["예순셋은 63이에요.","묶음 6개와 낱개 3개예요.","육십삼(이)라고도 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_b#12','math',1,2,'u1','review','g1_2_math_u1_review_b','unit_review','M1-2-u1-C5',2,'mc','auto','69보다 1만큼 더 큰 수는 얼마인가요?',ARRAY['M1-2-u1-X06','M1-2-u1-X05']::text[],false,'{"seq":12,"concept":"M1-2-u1-C5","difficulty":2,"kind":"mc","stem":"69보다 1만큼 더 큰 수는 얼마인가요?","options":[{"t":"70","correct":true},{"t":"79","mis":"M1-2-u1-X06"},{"t":"60","mis":"M1-2-u1-X05"}],"explanation":["낱개 9에 1을 더하면 10이에요.","낱개 10개를 묶으면 묶음이 하나 늘어요.","그래서 70이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_b#13','math',1,2,'u1','review','g1_2_math_u1_review_b','unit_review','M1-2-u1-C6',2,'sa','auto','74와 79 중에서 더 작은 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M1-2-u1-C6","difficulty":2,"kind":"sa","stem":"74와 79 중에서 더 작은 수를 숫자로 쓰세요.","answer":["74"],"explanation":["묶음이 둘 다 7개예요.","묶음이 같으니 낱개를 봐요 — 4와 9예요.","낱개가 적은 74가 작아요."],"variant_rule":{"cmp2":{"range":[21,98],"same_tens":true,"ask":"small"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_b#14','math',1,2,'u1','review','g1_2_math_u1_review_b','unit_review','M1-2-u1-C7',2,'ox','auto','둘씩 짝을 지어 보았어요. 15는 짝수입니다.',ARRAY['M1-2-u1-X09']::text[],true,'{"seq":14,"concept":"M1-2-u1-C7","difficulty":2,"kind":"ox","stem":"둘씩 짝을 지어 보았어요. 15는 짝수입니다.","asset":{"type":"pair_row","n":15},"answer":"X","reason_options":[{"t":"둘씩 짝지으면 하나가 남으니까","correct":true},{"t":"수가 크니까","mis":"M1-2-u1-X09"}],"explanation":["15를 둘씩 짝지어 보세요.","하나가 남으니 홀수예요.","남는 것이 있으면 홀수예요."],"variant_rule":{"parity":{"range":[3,19]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
