INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_b#24','math',1,2,'u1','review','g1_2_math_u1_review_b','unit_review','M1-2-u1-C2',4,'sa','auto','묶음이 5개, 낱개가 20개인 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M1-2-u1-C2","difficulty":4,"kind":"sa","stem":"묶음이 5개, 낱개가 20개인 수는 얼마인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["낱개 20개는 묶음 2개예요.","묶음이 모두 7개가 돼요.","그래서 70이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_b#25','math',1,2,'u1','review','g1_2_math_u1_review_b','unit_review','M1-2-u1-C4',4,'essay','teacher','43과 62 중에서 어느 수가 더 큰지 쓰고, 어떻게 알았는지 말해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u1-C4","difficulty":4,"kind":"essay","stem":"43과 62 중에서 어느 수가 더 큰지 쓰고, 어떻게 알았는지 말해 보세요.","answer_guide":"62(이)라고 답하고 「묶음(십의 자리)을 먼저 비교했다」는 까닭을 말하면 통과. 낱개로 판단했다면 다시 지도.","explanation":["묶음을 먼저 봐요 — 4개와 6개예요.","묶음이 많은 62가 커요.","낱개는 묶음이 같을 때만 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_c#1','math',1,2,'u1','review','g1_2_math_u1_review_c','unit_review','M1-2-u1-C1',1,'mc','auto','그림을 보세요. 얼마인가요?',ARRAY['M1-2-u1-X02','M1-2-u1-X01']::text[],true,'{"seq":1,"concept":"M1-2-u1-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 얼마인가요?","asset":{"type":"bundle_ones","tens":8,"ones":0},"options":[{"t":"80","correct":true},{"t":"8","mis":"M1-2-u1-X02"},{"t":"18","mis":"M1-2-u1-X01"}],"explanation":["10개씩 묶음이 8개예요.","묶음 8개는 80이에요.","묶음 하나는 낱개 10개와 같아요."],"variant_rule":{"bundle":{"tens":[6,9],"ones":[0,0],"ask":"number"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_c#2','math',1,2,'u1','review','g1_2_math_u1_review_c','unit_review','M1-2-u1-C2',1,'sa','auto','그림이 나타내는 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u1-C2","difficulty":1,"kind":"sa","stem":"그림이 나타내는 수를 숫자로 쓰세요.","asset":{"type":"bundle_ones","tens":7,"ones":6},"answer":["76"],"explanation":["묶음 7개는 70이에요.","낱개 6개를 더하면 76이에요.","묶음 수를 앞에, 낱개 수를 뒤에 써요."],"variant_rule":{"bundle":{"tens":[2,9],"ones":[1,9],"ask":"number"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_c#3','math',1,2,'u1','review','g1_2_math_u1_review_c','unit_review','M1-2-u1-C3',1,'mc','auto','82를 바르게 읽은 것은 무엇인가요?',ARRAY['M1-2-u1-X04','M1-2-u1-X02']::text[],false,'{"seq":3,"concept":"M1-2-u1-C3","difficulty":1,"kind":"mc","stem":"82를 바르게 읽은 것은 무엇인가요?","options":[{"t":"팔십이","correct":true},{"t":"팔십둘","mis":"M1-2-u1-X04"},{"t":"이","mis":"M1-2-u1-X02"}],"explanation":["82는 팔십이 또는 여든둘(이)라고 읽어요.","두 가지 읽기를 섞어 읽지 않아요.","한 가지 방법으로 끝까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_c#4','math',1,2,'u1','review','g1_2_math_u1_review_c','unit_review','M1-2-u1-C5',1,'sa','auto','수 배열판이에요. 빈칸에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u1-C5","difficulty":1,"kind":"sa","stem":"수 배열판이에요. 빈칸에 알맞은 수를 쓰세요.","asset":{"type":"hundred_chart","cells":[46,47,null,49,50,51],"cols":6},"answer":["48"],"explanation":["한 칸 갈 때마다 1씩 커져요.","47 다음은 48이에요.","앞뒤 칸을 보고 이어 세어요."],"variant_rule":{"chart":{"from":21,"to":94}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
