INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_c#6','math',1,2,'u1','review','g1_2_math_u1_review_c','unit_review','M1-2-u1-C7',1,'mc','auto','둘씩 짝을 지었어요. 12는 짝수인가요, 홀수인가요?',ARRAY['M1-2-u1-X09']::text[],true,'{"seq":6,"concept":"M1-2-u1-C7","difficulty":1,"kind":"mc","stem":"둘씩 짝을 지었어요. 12는 짝수인가요, 홀수인가요?","asset":{"type":"pair_row","n":12},"options":[{"t":"짝수","correct":true},{"t":"홀수","mis":"M1-2-u1-X09"}],"explanation":["12를 둘씩 짝지어 보세요.","남는 것이 없으니 짝수예요.","크기와는 관계없어요."],"variant_rule":{"parity":{"range":[4,20]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
