INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_c#25','math',1,2,'u1','review','g1_2_math_u1_review_c','unit_review','M1-2-u1-C4',4,'essay','teacher','64와 39 중에서 어느 수가 더 큰지 쓰고, 어떻게 알았는지 말해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u1-C4","difficulty":4,"kind":"essay","stem":"64와 39 중에서 어느 수가 더 큰지 쓰고, 어떻게 알았는지 말해 보세요.","answer_guide":"64(이)라고 답하고 「묶음(십의 자리)을 먼저 비교했다」는 까닭을 말하면 통과. 낱개로 판단했다면 다시 지도.","explanation":["묶음을 먼저 봐요 — 6개와 3개예요.","묶음이 많은 64가 커요.","낱개는 묶음이 같을 때만 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_d#1','math',1,2,'u1','review','g1_2_math_u1_review_d','unit_review','M1-2-u1-C1',1,'mc','auto','그림을 보세요. 얼마인가요?',ARRAY['M1-2-u1-X02','M1-2-u1-X01']::text[],true,'{"seq":1,"concept":"M1-2-u1-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 얼마인가요?","asset":{"type":"bundle_ones","tens":9,"ones":0},"options":[{"t":"90","correct":true},{"t":"9","mis":"M1-2-u1-X02"},{"t":"19","mis":"M1-2-u1-X01"}],"explanation":["10개씩 묶음이 9개예요.","묶음 9개는 90이에요.","묶음 하나는 낱개 10개와 같아요."],"variant_rule":{"bundle":{"tens":[6,9],"ones":[0,0],"ask":"number"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_d#2','math',1,2,'u1','review','g1_2_math_u1_review_d','unit_review','M1-2-u1-C2',1,'sa','auto','그림이 나타내는 수를 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u1-C2","difficulty":1,"kind":"sa","stem":"그림이 나타내는 수를 숫자로 쓰세요.","asset":{"type":"bundle_ones","tens":2,"ones":8},"answer":["28"],"explanation":["묶음 2개는 20이에요.","낱개 8개를 더하면 28이에요.","묶음 수를 앞에, 낱개 수를 뒤에 써요."],"variant_rule":{"bundle":{"tens":[2,9],"ones":[1,9],"ask":"number"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
