INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_d#4','math',1,2,'u1','review','g1_2_math_u1_review_d','unit_review','M1-2-u1-C5',1,'sa','auto','수 배열판이에요. 빈칸에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u1-C5","difficulty":1,"kind":"sa","stem":"수 배열판이에요. 빈칸에 알맞은 수를 쓰세요.","asset":{"type":"hundred_chart","cells":[54,55,null,57,58,59],"cols":6},"answer":["56"],"explanation":["한 칸 갈 때마다 1씩 커져요.","55 다음은 56이에요.","앞뒤 칸을 보고 이어 세어요."],"variant_rule":{"chart":{"from":21,"to":94}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
