INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_d#18','math',1,2,'u1','review','g1_2_math_u1_review_d','unit_review','M1-2-u1-C5',3,'sa','auto','수를 거꾸로 세었어요. 빈칸에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M1-2-u1-C5","difficulty":3,"kind":"sa","stem":"수를 거꾸로 세었어요. 빈칸에 알맞은 수를 쓰세요.","asset":{"type":"hundred_chart","cells":[71,70,69,null,67,66],"cols":6},"answer":["68"],"explanation":["거꾸로 세면 1씩 작아져요.","69 다음은 68이에요.","앞뒤 칸을 보고 세어요."],"variant_rule":{"chart":{"from":31,"to":96,"dir":"back"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
