INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_d#24','math',1,2,'u1','review','g1_2_math_u1_review_d','unit_review','M1-2-u1-C2',4,'sa','auto','묶음이 4개, 낱개가 20개인 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M1-2-u1-C2","difficulty":4,"kind":"sa","stem":"묶음이 4개, 낱개가 20개인 수는 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["낱개 20개는 묶음 2개예요.","묶음이 모두 6개가 돼요.","그래서 60이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u1_review_d#25','math',1,2,'u1','review','g1_2_math_u1_review_d','unit_review','M1-2-u1-C4',4,'essay','teacher','86과 59 중에서 어느 수가 더 큰지 쓰고, 어떻게 알았는지 말해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-2-u1-C4","difficulty":4,"kind":"essay","stem":"86과 59 중에서 어느 수가 더 큰지 쓰고, 어떻게 알았는지 말해 보세요.","answer_guide":"86(이)라고 답하고 「묶음(십의 자리)을 먼저 비교했다」는 까닭을 말하면 통과. 낱개로 판단했다면 다시 지도.","explanation":["묶음을 먼저 봐요 — 8개와 5개예요.","묶음이 많은 86이 커요.","낱개는 묶음이 같을 때만 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
